// <auto-generated/>

using System;
using System.Collections.Generic;
using System.Windows.Forms;
using CargoWise.Common;
using Enterprise.Freight.Forwarding.Business;
using Enterprise.Freight.Forwarding.Orders.Business;
using Enterprise.ZArchitecture.Environment;
using Enterprise.ZArchitecture.GUI;
using Enterprise.ZArchitecture.Modules;

namespace Enterprise.Freight.Forwarding.GUI
{
	public partial class SelectOrdersForm : ZChildForm
	{
		public static void ShowForm(ForwardingShipment shipment)
		{
			Argument.NotNull(shipment, "shipment");
			ZFormModaliser.ShowDialogAndDispose(new SelectOrdersForm(shipment));
		}

		#region Constructors

		protected SelectOrdersForm(ForwardingShipment shipment)
			: base(shipment)
		{
			InitializeComponent();
			Shipment = shipment;
		}

		readonly ForwardingShipment Shipment;

		SelectOrdersForm()
		{
			InitializeComponent();
		}

		void SelectOrdersForm_Load(object sender, EventArgs e)
		{
			if (OrdersGrid.ListManager.Count == 1)
			{
				OrdersGrid.Select(0);
				ActiveControl = SelectButton;
			}
		}

		#endregion

		#region Implementation

		void SelectButton_Click(object sender, EventArgs e)
		{
			if (OrdersGrid.SelectedRowCount == 0)
			{
				Globals.Message.Show(Res.GetString("55496389-f291-4ef6-bf81-c966e2d7d28b", "No Orders selected"));
				return;
			}

			var selectedOrders = OrdersGrid.SelectedElements;
			if (selectedOrders.Length > 0 && Shipment != null)
			{
				var ordersToBeAttached = new List<Order>();
				foreach (Order selectedOrder in selectedOrders)
				{
					if (!selectedOrder.JD_JS.IsEmpty && selectedOrder.JD_JS != Shipment.PK)
					{
						//TODO: If the Order is attached to an uncommitted shipment which has been deleted, should allow attach.
						Globals.Message.ShowInformation(Res.GetString("37fd3dad-3e78-43d4-b01a-81a701503643", "Selected Order is already attached to another Shipment."), Res.GetString("d3b0e0b8-9b54-4141-8995-5cf0e5fb5f41", "Attach Related Order"));
					}
					else
					{
						ordersToBeAttached.Add(selectedOrder);
					}
				}

				Shipment.CreatePackLinesFromOrderLines(ordersToBeAttached);
				Shipment.AttachedOrders.AddRange(ordersToBeAttached);
			}

			Close();
		}

		void OrdersGrid_DoubleClick(object sender, EventArgs e)
		{
			DataGrid.HitTestInfo hit = OrdersGrid.HitTest(OrdersGrid.PointToClient(Control.MousePosition));
			if (hit.Row >= 0)
			{
				ViewOrder((Order)OrdersGrid.ListManager.List[hit.Row]);
			}
		}

		void ViewOrder(Order orderToShow)
		{
			if (orderToShow.PK.IsValid)
			{
				ZController orderController = ZControllerFactory.Create(ControllerIDs.Orders);
				orderController.ShowViewForm(orderToShow);
			}
		}

		#endregion
	}
}
